import { useUWB } from '@pixelkit-labs/sdk';

function Radar({ peer }: { peer: { address: string; sessionId: number; channel: number; preambleIndex: number } }) {
  const { isSupported, isRanging, measurements, sessionError, startRanging, stopRanging } = useUWB();
  if (!isSupported) return <Text>No UWB radio</Text>;
  return (
    <View>
      <Button
        title={isRanging ? 'Stop session' : 'Range with peer'}
        onPress={() => isRanging ? stopRanging() : startRanging({
          sessionId: peer.sessionId,
          role: 'initiator',
          localAddress: '0x1234',
          peerAddress: peer.address,
          channel: peer.channel,
          preambleIndex: peer.preambleIndex,
        })}
      />
      {sessionError ? <Text>{sessionError}</Text> : null}
      {measurements.map((m) => (
        <Text key={m.deviceId}>{m.distanceMeters == null ? '—' : `${m.distanceMeters.toFixed(2)} m`}</Text>
      ))}
    </View>
  );
}
